let sb=null, state={lang:localStorage.getItem('tk_lang')||'ar', categories:[], content:[], prompts:[], user:null, isAdmin:false, favorites:new Set(JSON.parse(localStorage.getItem('tk_favorites')||'[]')), booted:false};
const $=s=>document.querySelector(s); const app=$('#app'); const t=()=>TX[state.lang]||TX.ar;
function esc(v=''){return String(v).replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#039;','"':'&quot;'}[c]))}
function arr(v){return Array.isArray(v)?v:(typeof v==='string'&&v?v.split(',').map(x=>x.trim()).filter(Boolean):[])}
function slugify(s){return String(s||'').normalize('NFKD').replace(/[\u0300-\u036f]/g,'').toLowerCase().trim().replace(/[^\w\-\s]+/g,'').replace(/\s+/g,'-').replace(/-+/g,'-').slice(0,70)||`item-${Date.now()}`}
function langTitle(item){return item[`title_${state.lang}`]||item.title_en||item.title||item.title_ar||item.title_fr||'Untitled'}
function langDesc(item){return item[`description_${state.lang}`]||item.description_en||item.description||item.description_ar||item.description_fr||''}
function catName(cat){return cat?.[`name_${state.lang}`]||cat?.name_en||cat?.name_ar||''}
function categoryMap(){return new Map(state.categories.map(c=>[c.id,c]))}
function typeLabel(type){return ({app:t().apps,website:t().websites,tool:t().tools,ai_tool:t().ai,prompt:t().prompts})[type]||type}
function pricingLabel(p){return t()[p]||p||t().unknown}
function iconSvg(type){return type==='app'?'📱':type==='website'?'🌐':type==='ai_tool'?'🤖':type==='prompt'?'🧠':'🛠️'}
function card(item){
  const isFav=state.favorites.has(item.id), cat=categoryMap().get(item.category_id);
  return `<article class="card">
    <a href="/${item.type==='app'?'apps':item.type==='website'?'websites':item.type==='tool'?'tools':item.type==='ai_tool'?'ai':'prompts'}/${esc(item.slug)}">
      <div class="card-media">${item.cover_image||item.preview_image?`<img loading="lazy" src="${esc(item.cover_image||item.preview_image)}" alt="">`:`<div class="icon-fallback">${iconSvg(item.type)}</div>`}${item.featured?`<span class="featured-badge">★ ${t().featuredLabel}</span>`:''}</div>
    </a>
    <div class="card-body">
      <div class="card-top"><div class="card-icon">${item.icon?`<img loading="lazy" src="${esc(item.icon)}" alt="">`:iconSvg(item.type)}</div><div style="min-width:0;flex:1"><h3>${esc(langTitle(item))}</h3><p>${esc(langDesc(item))}</p></div><button class="fav ${isFav?'active':''}" data-fav="${esc(item.id)}" aria-label="${esc(t().favorites)}">${I('heart',19)}</button></div>
      <div class="meta-row"><span class="type-badge">${esc(typeLabel(item.type))}</span>${cat?`<span class="tag">${esc(catName(cat))}</span>`:''}<span class="tag">${esc(pricingLabel(item.pricing))}</span></div>
    </div></article>`
}
function shell(inner, opts={}){
  document.documentElement.lang=state.lang;document.documentElement.dir=t().dir;document.body.dir=t().dir;
  const avatar=state.user?.user_metadata?.avatar_url||state.user?.user_metadata?.picture;
  app.innerHTML=`<div class="app-shell"><header class="topbar"><div class="container topbar-inner">
    <a class="brand" href="/">${brandMark()}<span class="brand-text">theking._.edit</span></a>
    <div class="top-search"><span class="search-icon">${I('search')}</span><input id="global-search" placeholder="${esc(t().search)}" value="${esc(opts.search||'')}"></div>
    <div class="actions"><button class="lang-btn" id="lang-menu">${state.lang.toUpperCase()} ${I('chevron',16)}</button>${state.user&&state.isAdmin?`<a class="user-pill" href="/admin">${avatar?`<img src="${esc(avatar)}" alt="">`:''}<span>${esc(state.user.email||t().admin)}</span></a>`:`<a class="icon-btn" href="/favorites" title="${esc(t().favorites)}">${I('heart')}</a>`}</div>
  </div></header>${inner}<nav class="mobile-nav"><div class="mobile-nav-inner"><button data-nav="/"><span>${I('grid',18)}</span><span>${esc(t().site.split(' ')[0]||t().apps)}</span></button><button data-nav="/search"><span>${I('search',18)}</span><span>${esc(t().search.split(' ')[0])}</span></button><button data-nav="/favorites"><span>${I('heart',18)}</span><span>${esc(t().favorites)}</span></button><button data-nav="${state.user&&state.isAdmin?'/admin':'/'}"><span>${I(state.user&&state.isAdmin?'dashboard':'menu',18)}</span><span>${esc(state.user&&state.isAdmin?t().admin:t().more)}</span></button></div></nav></div>`;
  bindGlobal();
}
function brandMark(){return `<div class="brand-mark"><svg viewBox="0 0 64 64" fill="none"><path d="M14 23l8 8 10-16 10 16 8-8-2 25H16z" fill="#11110d"/><path d="M19 47h26" stroke="#11110d" stroke-width="3" stroke-linecap="round"/></svg></div>`}
function bindGlobal(){
  $('#global-search')?.addEventListener('keydown',e=>{if(e.key==='Enter'){const q=e.currentTarget.value.trim();location.href=q?`/search?q=${encodeURIComponent(q)}`:'/search'}});
  $('#lang-menu')?.addEventListener('click',()=>openLanguageModal());
  document.querySelectorAll('[data-fav]').forEach(b=>b.addEventListener('click',e=>{e.preventDefault();e.stopPropagation();toggleFav(e.currentTarget.dataset.fav)}));
  document.querySelectorAll('[data-admin-nav]').forEach(b=>b.addEventListener('click',()=>{const u=b.dataset.adminNav;if(u==='#')openAddChooser();else location.href=u}));
  document.querySelectorAll('#admin-logout').forEach(b=>b.addEventListener('click',async()=>{await sb.auth.signOut();location.href='/'}));
  document.querySelectorAll('.mobile-nav [data-nav]').forEach(b=>b.addEventListener('click',()=>location.href=b.dataset.nav));
}
function openLanguageModal(){
  const m=document.createElement('div');m.className='modal';m.innerHTML=`<div class="modal-card" style="max-width:420px"><div class="modal-head"><h3>${esc(t().menu)}</h3><button class="close">${I('close')}</button></div><div class="language-grid" style="margin-top:18px">${[['ar','العربية'],['en','English'],['fr','Français']].map(([k,n])=>`<button class="language ${state.lang===k?'active':''}" data-set-lang="${k}">${n}</button>`).join('')}</div></div>`;document.body.appendChild(m);m.querySelector('.close').onclick=()=>m.remove();m.addEventListener('click',e=>{if(e.target===m)m.remove()});m.querySelectorAll('[data-set-lang]').forEach(b=>b.onclick=()=>{state.lang=b.dataset.setLang;localStorage.setItem('tk_lang',state.lang);m.remove();router()})
}
function toggleFav(id){if(state.favorites.has(id))state.favorites.delete(id);else state.favorites.add(id);localStorage.setItem('tk_favorites',JSON.stringify([...state.favorites]));document.querySelectorAll(`[data-fav="${CSS.escape(id)}"]`).forEach(b=>b.classList.toggle('active',state.favorites.has(id)))}
function toast(msg,kind='ok'){const r=$('#toast-root');const s=document.createElement('div');s.className=`toast ${kind}`;s.textContent=msg;r.appendChild(s);setTimeout(()=>s.remove(),3200)}

async function loadConfig(){
  if(window.THEKING_CONFIG?.SUPABASE_URL) return {supabaseUrl:window.THEKING_CONFIG.SUPABASE_URL,supabaseAnonKey:window.THEKING_CONFIG.SUPABASE_ANON_KEY,siteUrl:window.THEKING_CONFIG.SITE_URL};
  const r=await fetch('/api/config'); if(!r.ok) throw new Error('Config endpoint unavailable'); return await r.json();
}
async function init(){
  try{const cfg=await loadConfig(); if(!cfg.supabaseUrl||!cfg.supabaseAnonKey) throw new Error('Missing Supabase configuration'); const mod=await import(SUPABASE_CDN); sb=mod.createClient(cfg.supabaseUrl,cfg.supabaseAnonKey,{auth:{persistSession:true,autoRefreshToken:true,detectSessionInUrl:true}}); const {data:{session}}=await sb.auth.getSession();state.user=session?.user||null; if(state.user) await refreshAdmin(); await Promise.all([loadCategories(),loadPublicContent()]); state.booted=true; await router();
    sb.auth.onAuthStateChange(async(_e,s)=>{state.user=s?.user||null; if(state.user) await refreshAdmin(); else state.isAdmin=false; if(location.pathname.startsWith('/admin')) router();});
  }catch(e){console.error(e); app.innerHTML=`<div class="container"><div class="login-box"><div class="brand-mark" style="margin:auto">${brandMark().replace('brand-mark','')}</div><h1>theking._.edit</h1><p>${esc(t().errorGeneric)}<br><span class="subtle">Configure Supabase in config.js or Pages environment variables.</span></p></div></div>`}
}
async function refreshAdmin(){try{const {data,error}=await sb.rpc('is_admin');state.isAdmin=!error&&data===true}catch{state.isAdmin=false}}
async function loadCategories(){const {data}=await sb.from('categories').select('*').order('sort_order');state.categories=data?.length?data:CATEGORIES_FALLBACK.map((x,i)=>({id:`fallback-${i}`,slug:x[0],name_ar:x[1],name_en:x[2],name_fr:x[3],icon:x[4],sort_order:i}))}
async function loadPublicContent(){
  const [{data:c},{data:p}]=await Promise.all([
    sb.from('content').select('*').eq('published',true).is('deleted_at',null).order('created_at',{ascending:false}).limit(500),
    sb.from('prompts').select('*').eq('published',true).is('deleted_at',null).order('created_at',{ascending:false}).limit(500)
  ]);state.content=c||[];state.prompts=(p||[]).map(x=>({...x,type:'prompt',preview_image:x.preview_image}));
}
function allPublished(){return [...state.content,...state.prompts]}

function home(){setSeo('theking._.edit',t().heroDesc,'/');
  const all=allPublished(), featured=all.filter(x=>x.featured).slice(0,8), latest=all.slice(0,12);
  shell(`<main class="main"><div class="container"><section class="hero"><span class="eyebrow">👑 theking._.edit</span><h1>${esc(t().hero)}</h1><p>${esc(t().heroDesc)}</p><div class="hero-search"><span class="search-icon">${I('search',23)}</span><input id="hero-search" placeholder="${esc(t().search)}"></div></section>
    <section class="section"><div class="section-head"><div><h2>${esc(t().categories)}</h2><p>${esc(t().site)}</p></div></div><div class="chips">${state.categories.map(c=>`<button class="chip" data-cat="${esc(c.slug)}">${esc(c.icon||'•')} ${esc(catName(c))}</button>`).join('')}</div></section>
    ${featured.length?`<section class="section"><div class="section-head"><div><h2>${esc(t().featured)}</h2></div><a class="link-btn" href="/search?featured=1">${esc(t().explore)} ${I(t().dir==='rtl'?'back':'arrow',16)}</a></div><div class="grid">${featured.map(card).join('')}</div></section>`:''}
    <section class="section"><div class="section-head"><div><h2>${esc(t().latest)}</h2></div><a class="link-btn" href="/search">${esc(t().explore)} ${I(t().dir==='rtl'?'back':'arrow',16)}</a></div>${latest.length?`<div class="grid">${latest.map(card).join('')}</div>`:`<div class="empty"><strong>${esc(t().noContent)}</strong></div>`}</section>
  </div></main><footer class="footer"><div class="container">theking._.edit · Discover Apps · Tools · Websites · AI · Prompts</div></footer>`);
  $('#hero-search')?.addEventListener('keydown',e=>{if(e.key==='Enter'){const q=e.currentTarget.value.trim();if(q)location.href=`/search?q=${encodeURIComponent(q)}`}});
  document.querySelectorAll('[data-cat]').forEach(b=>b.addEventListener('click',()=>location.href=`/search?cat=${encodeURIComponent(b.dataset.cat)}`));
}
function searchPage(){setSeo(t().all,t().heroDesc,'/search');
  const params=new URLSearchParams(location.search), q=(params.get('q')||'').trim().toLowerCase(), cat=params.get('cat')||'', type=params.get('type')||'', price=params.get('price')||'', platform=params.get('platform')||'', featured=params.get('featured')==='1';
  let rows=allPublished();const cmap=categoryMap();
  if(q)rows=rows.filter(x=>[langTitle(x),langDesc(x),x.title,x.title_ar,x.title_en,x.title_fr,x.description,x.description_ar,x.description_en,x.description_fr,...arr(x.tags),cmap.get(x.category_id)?.slug,cmap.get(x.category_id)?.name_en].join(' ').toLowerCase().includes(q));
  if(cat)rows=rows.filter(x=>cmap.get(x.category_id)?.slug===cat); if(type)rows=rows.filter(x=>x.type===type); if(price)rows=rows.filter(x=>x.pricing===price); if(platform)rows=rows.filter(x=>arr(x.platform).some(v=>v.toLowerCase()===platform.toLowerCase())); if(featured)rows=rows.filter(x=>x.featured);
  shell(`<main class="main"><div class="container"><section class="section" style="margin-top:10px"><div class="section-head"><div><h2>${esc(q||t().all)}</h2><p>${rows.length} ${esc(t().latest.toLowerCase())}</p></div><a class="link-btn" href="/">${esc(t().back)}</a></div><div class="admin-toolbar"><input class="input" id="search-page-input" style="max-width:460px" placeholder="${esc(t().search)}" value="${esc(q)}"></div><div class="chips" style="margin-bottom:18px"><button class="chip ${!type?'active':''}" data-f="all">${esc(t().all)}</button><button class="chip ${type==='app'?'active':''}" data-f="type=app">${esc(t().apps)}</button><button class="chip ${type==='website'?'active':''}" data-f="type=website">${esc(t().websites)}</button><button class="chip ${type==='tool'?'active':''}" data-f="type=tool">${esc(t().tools)}</button><button class="chip ${type==='ai_tool'?'active':''}" data-f="type=ai_tool">${esc(t().ai)}</button><button class="chip ${type==='prompt'?'active':''}" data-f="type=prompt">${esc(t().prompts)}</button><button class="chip ${price==='free'?'active':''}" data-f="price=free">${esc(t().free)}</button><button class="chip ${price==='freemium'?'active':''}" data-f="price=freemium">${esc(t().freemium)}</button><button class="chip ${platform==='Google Play'?'active':''}" data-f="platform=Google%20Play">Google Play</button><button class="chip ${platform==='App Store'?'active':''}" data-f="platform=App%20Store">App Store</button><button class="chip ${platform==='Web'?'active':''}" data-f="platform=Web">Web</button></div>${rows.length?`<div class="grid">${rows.map(card).join('')}</div>`:`<div class="empty"><strong>${esc(t().emptySearch)}</strong><span>${esc(t().noContent)}</span></div>`}</section></div></main>`);
  $('#search-page-input')?.addEventListener('keydown',e=>{if(e.key==='Enter'){const v=e.currentTarget.value.trim();location.href=v?`/search?q=${encodeURIComponent(v)}`:'/search'}});
  document.querySelectorAll('[data-f]').forEach(b=>b.onclick=()=>{const extra=b.dataset.f==='all'?'':b.dataset.f;const u=new URL(location.href);u.searchParams.delete('type');u.searchParams.delete('price');u.searchParams.delete('platform');if(extra){const [k,v]=extra.split('=');u.searchParams.set(k,v)}location.href=u.pathname+(u.search?'?'+u.searchParams.toString():'')});
}
function favoritesPage(){setSeo(t().favorites,t().noFav,'/favorites');const rows=allPublished().filter(x=>state.favorites.has(x.id));shell(`<main class="main"><div class="container"><section class="section" style="margin-top:12px"><div class="section-head"><div><h2>${esc(t().favorites)}</h2></div></div>${rows.length?`<div class="grid">${rows.map(card).join('')}</div>`:`<div class="empty"><strong>${esc(t().noFav)}</strong><span class="subtle">${esc(t().noContent)}</span></div>`}</section></div></main>`)}

function setSeo(title,description='',path=location.pathname,image=''){ document.title=title?`${title} · theking._.edit`:'theking._.edit';const md=document.querySelector('meta[name=description]');if(md)md.content=description||t().heroDesc;const ogt=document.querySelector('meta[property=og\:title]');if(ogt)ogt.content=title||'theking._.edit';const ogd=document.querySelector('meta[property=og\:description]');if(ogd)ogd.content=description||t().heroDesc;const ogi=document.querySelector('meta[property=og\:image]');if(ogi)ogi.content=image||`${location.origin}/assets/og-cover.svg`;const can=document.querySelector('link[rel=canonical]');if(can)can.href=(window.location.origin||'')+path;let ld=document.getElementById('page-jsonld');if(ld)ld.remove();const script=document.createElement('script');script.id='page-jsonld';script.type='application/ld+json';script.textContent=JSON.stringify({"@context":"https://schema.org","@type":"WebPage",name:title||'theking._.edit',description:description||t().heroDesc,url:location.href});document.head.appendChild(script)}

function detailPage(kind,slug){const map={apps:'app',websites:'website',tools:'tool',ai:'ai_tool',prompts:'prompt'};const type=map[kind];const rows=type==='prompt'?state.prompts:state.content;const item=rows.find(x=>x.slug===slug);if(!item)return notFound();setSeo(langTitle(item),langDesc(item),location.pathname,item.cover_image||item.preview_image||item.icon||'');const cat=categoryMap().get(item.category_id);const links=[];if(item.google_play_url)links.push(`<a class="btn primary" target="_blank" rel="noopener noreferrer" href="${esc(item.google_play_url)}">${esc(t().play)}</a>`);if(item.app_store_url)links.push(`<a class="btn primary" target="_blank" rel="noopener noreferrer" href="${esc(item.app_store_url)}">${esc(t().appstore)}</a>`);if(item.official_url)links.push(`<a class="btn primary" target="_blank" rel="noopener noreferrer" href="${esc(item.official_url)}">${esc(type==='tool'||type==='ai_tool'?t().use:t().visit)}</a>`);if(item.other_official_url)links.push(`<a class="btn" target="_blank" rel="noopener noreferrer" href="${esc(item.other_official_url)}">${esc(t().other)}</a>`);
  if(type==='prompt')return promptDetail(item,cat);
  shell(`<main class="main"><div class="container detail"><a class="back" href="javascript:history.back()">${I(t().dir==='rtl'?'arrow':'back',16)} ${esc(t().back)}</a><section class="detail-hero"><div class="detail-icon">${item.icon?`<img src="${esc(item.icon)}" alt="">`:iconSvg(type)}</div><div><span class="type-badge">${esc(typeLabel(type))}</span><h1>${esc(langTitle(item))}</h1><p class="detail-sub">${esc(langDesc(item))}</p><div class="meta-row">${cat?`<span class="tag">${esc(catName(cat))}</span>`:''}<span class="tag">${esc(pricingLabel(item.pricing))}</span>${item.featured?`<span class="type-badge">★ ${esc(t().featuredLabel)}</span>`:''}</div><div class="cta-row">${links.join('')}<button class="btn" data-fav="${esc(item.id)}">${I('heart')} ${esc(t().favorites)}</button></div></div></section><section class="detail-body"><div class="panel"><h2>${esc(t().details)}</h2><div class="rich">${esc(item[`full_description_${state.lang}`]||item.full_description||item[`full_description_${state.lang==='ar'?'en':state.lang}`]||langDesc(item))}</div>${arr(item.features).length?`<div class="section" style="margin-top:24px"><h2>${esc(t().features)}</h2><div class="chips">${arr(item.features).map(x=>`<span class="chip active">${esc(x)}</span>`).join('')}</div></div>`:''}</div><aside class="panel"><h2>${esc(t().facts)}</h2><div class="facts">${cat?`<div class="fact"><span>${esc(t().category)}</span><b>${esc(catName(cat))}</b></div>`:''}<div class="fact"><span>${esc(t().pricing)}</span><b>${esc(pricingLabel(item.pricing))}</b></div>${arr(item.platform).length?`<div class="fact"><span>${esc(t().platform)}</span><b>${esc(item.platform.join(', '))}</b></div>`:''}${arr(item.languages).length?`<div class="fact"><span>${esc(t().languages)}</span><b>${esc(item.languages.join(', '))}</b></div>`:''}${item.developer?`<div class="fact"><span>${esc(t().developer)}</span><b>${esc(item.developer)}</b></div>`:''}${item.company?`<div class="fact"><span>${esc(t().company)}</span><b>${esc(item.company)}</b></div>`:''}</div>${arr(item.tags).length?`<div style="margin-top:20px"><h2>${esc(t().tags)}</h2><div class="chips">${arr(item.tags).map(x=>`<span class="chip">#${esc(x)}</span>`).join('')}</div></div>`:''}</aside></section>${arr(item.screenshots).length?`<section class="panel" style="margin-top:18px"><h2>${esc(t().screenshots)}</h2><div class="screens">${arr(item.screenshots).map(x=>`<img loading="lazy" src="${esc(x)}" alt="">`).join('')}</div></section>`:''}</div></main>`);}
function promptDetail(item,cat){shell(`<main class="main"><div class="container detail"><a class="back" href="javascript:history.back()">${I(t().dir==='rtl'?'arrow':'back',16)} ${esc(t().back)}</a><section class="detail-hero"><div class="detail-icon">${item.icon?`<img src="${esc(item.icon)}" alt="">`:'🧠'}</div><div><span class="type-badge">${esc(t().prompts)}</span><h1>${esc(langTitle(item))}</h1><p class="detail-sub">${esc(langDesc(item))}</p><div class="meta-row">${cat?`<span class="tag">${esc(catName(cat))}</span>`:''}${item.ai_tool?`<span class="tag">${esc(item.ai_tool)}</span>`:''}${item.language?`<span class="tag">${esc(item.language)}</span>`:''}</div><div class="cta-row"><button class="btn primary" id="detail-copy">${I('copy')} ${esc(t().copy)}</button><button class="btn" data-fav="${esc(item.id)}">${I('heart')} ${esc(t().favorites)}</button></div></div></section><section class="detail-body"><div class="panel"><h2>${esc(t().prompt)}</h2><div class="prompt-box"><button class="copy-btn" id="detail-copy-2">${I('copy',17)}</button><pre id="prompt-text">${esc(item.prompt)}</pre></div></div><aside class="panel"><h2>${esc(t().facts)}</h2><div class="facts">${cat?`<div class="fact"><span>${esc(t().category)}</span><b>${esc(catName(cat))}</b></div>`:''}${item.ai_tool?`<div class="fact"><span>${esc(t().aiTool)}</span><b>${esc(item.ai_tool)}</b></div>`:''}${item.language?`<div class="fact"><span>${esc(t().language)}</span><b>${esc(item.language)}</b></div>`:''}${item.result_type?`<div class="fact"><span>${esc(t().resultType)}</span><b>${esc(item.result_type)}</b></div>`:''}</div>${arr(item.tags).length?`<div style="margin-top:20px"><h2>${esc(t().tags)}</h2><div class="chips">${arr(item.tags).map(x=>`<span class="chip">#${esc(x)}</span>`).join('')}</div></div>`:''}</aside></section>${item.preview_image?`<section class="panel" style="margin-top:18px"><img src="${esc(item.preview_image)}" alt="" style="width:100%;max-height:620px;object-fit:cover;border-radius:15px;border:1px solid var(--line)"></section>`:''}</div></main>`);const copy=()=>navigator.clipboard?.writeText(item.prompt).then(()=>toast(t().copied,'ok')).catch(()=>toast(t().errorGeneric,'error'));$('#detail-copy')?.addEventListener('click',copy);$('#detail-copy-2')?.addEventListener('click',copy)}
function notFound(){shell(`<main class="main"><div class="container"><div class="empty" style="margin-top:50px"><strong>404</strong><span>${esc(t().noContent)}</span><div style="margin-top:16px"><a class="btn primary" href="/">${esc(t().back)}</a></div></div></div></main>`)}

function welcome(){app.innerHTML=`<div class="welcome"><div class="welcome-card"><div class="crown">${brandMark()}</div><h1>${esc(t().welcomeTitle)}</h1><p>${esc(t().welcomeDesc)}</p><div class="language-grid">${[['ar','العربية'],['en','English'],['fr','Français']].map(([k,n])=>`<button class="language ${state.lang===k?'active':''}" data-lang="${k}">${n}</button>`).join('')}</div><button class="btn primary" id="start-browse" style="width:100%;justify-content:center;height:52px">${esc(t().continue)} ${I(t().dir==='rtl'?'back':'arrow',18)}</button></div></div>`;document.querySelectorAll('[data-lang]').forEach(b=>b.onclick=()=>{state.lang=b.dataset.lang;localStorage.setItem('tk_lang',state.lang);welcome()});$('#start-browse').onclick=()=>{localStorage.setItem('tk_welcomed','1');router()}}

function adminLogin(){shell(`<main class="main"><div class="container"><div class="login-box"><div class="crown" style="margin-bottom:12px">${brandMark()}</div><h1>${esc(t().dashboard)}</h1><p>${esc(t().notAdmin)}<br>${esc(t().google)}</p><button class="btn primary" id="google-login" style="width:100%;justify-content:center;margin-top:10px">${esc(t().google)}</button></div></div></main>`);$('#google-login').onclick=async()=>{const {error}=await sb.auth.signInWithOAuth({provider:'google',options:{redirectTo:location.origin+'/admin'}});if(error)toast(error.message,'error')};}
function adminDashboard(){const rows=allAdminRows();const stats={total:rows.length,apps:state.content.filter(x=>x.type==='app').length,web:state.content.filter(x=>x.type==='website').length,tools:state.content.filter(x=>x.type==='tool').length,ai:state.content.filter(x=>x.type==='ai_tool').length,prompts:state.prompts.length,pub:rows.filter(x=>x.published).length,draft:rows.filter(x=>!x.published).length,feat:rows.filter(x=>x.featured).length};
  shell(adminChrome('dashboard',`<div class="admin-head"><div><h1>${esc(t().dashboard)}</h1><span class="subtle">${esc(state.user?.email||'')}</span></div><button class="btn primary" id="open-add">${I('plus')} ${esc(t().add)}</button></div><div class="stats"><div class="stat"><div class="n">${stats.total}</div><div class="l">${esc(t().total)}</div></div><div class="stat"><div class="n">${stats.apps}</div><div class="l">${esc(t().apps)}</div></div><div class="stat"><div class="n">${stats.web}</div><div class="l">${esc(t().websites)}</div></div><div class="stat"><div class="n">${stats.tools}</div><div class="l">${esc(t().tools)}</div></div><div class="stat"><div class="n">${stats.ai}</div><div class="l">${esc(t().ai)}</div></div><div class="stat"><div class="n">${stats.prompts}</div><div class="l">${esc(t().prompts)}</div></div><div class="stat"><div class="n">${stats.pub}</div><div class="l">${esc(t().published)}</div></div><div class="stat"><div class="n">${stats.draft}</div><div class="l">${esc(t().drafts)}</div></div><div class="stat"><div class="n">${stats.feat}</div><div class="l">${esc(t().featuredLabel)}</div></div></div><section class="section"><div class="section-head"><div><h2>${esc(t().latestContent)}</h2></div></div>${adminTable(rows.slice(0,30))}</section>`));$('#open-add').onclick=()=>openAddChooser();}
function adminChrome(active,inner){return `<main><div class="admin-layout"><aside class="admin-side"><h2>theking._.edit</h2><div class="admin-menu">${[['dashboard',t().dashboard,'/admin'],['content',t().total,'/admin/content'],['add',t().add,'#'],['categories',t().categories,'/admin/categories'],['settings',t().settings,'/admin/settings']].map(([k,n,u])=>`<button class="${active===k?'active':''}" data-admin-nav="${u}" data-admin-key="${k}">${esc(n)}</button>`).join('')}<button id="admin-logout">${I('logout',18)} ${esc(t().logout)}</button></div></aside><div class="admin-main">${inner}</div></div></main>`}
function allAdminRows(){return [...state.content,...state.prompts].sort((a,b)=>new Date(b.updated_at||b.created_at)-new Date(a.updated_at||a.created_at))}
function adminTable(rows){const cmap=categoryMap();return `<div class="table-wrap"><table class="table"><thead><tr><th>${esc(t().name)}</th><th>${esc(t().type)}</th><th>${esc(t().category)}</th><th>${esc(t().status)}</th><th>${esc(t().featuredLabel)}</th><th></th></tr></thead><tbody>${rows.length?rows.map(x=>`<tr><td><div class="row-title"><div class="row-icon">${x.icon?`<img src="${esc(x.icon)}" alt="">`:iconSvg(x.type)}</div><div><b>${esc(langTitle(x))}</b><div class="subtle">/${esc(x.slug)}</div></div></div></td><td>${esc(typeLabel(x.type))}</td><td>${esc(catName(cmap.get(x.category_id))||'—')}</td><td><span class="status ${x.published?'pub':'draft'}">${x.published?esc(t().publishedStatus):esc(t().draft)}</span></td><td>${x.featured?'★':''}</td><td><div class="table-actions"><button class="btn mini" data-edit="${esc(x.id)}">${I('edit',15)} ${esc(t().edit)}</button></div></td></tr>`).join(''):`<tr><td colspan="6"><div class="empty">${esc(t().noContent)}</div></td></tr>`}</tbody></table></div>`}

function openAddChooser(){const m=document.createElement('div');m.className='modal';const opts=[['quick','🔗',t().quickAdd],['app','📱',t().apps],['website','🌐',t().websites],['tool','🛠️',t().tools],['ai_tool','🤖',t().ai],['prompt','🧠',t().addPrompt]];m.innerHTML=`<div class="modal-card"><div class="modal-head"><h3>${esc(t().add)}</h3><button class="close">${I('close')}</button></div><div class="grid" style="margin-top:18px;grid-template-columns:repeat(2,minmax(0,1fr))">${opts.map(([k,i,n])=>`<button class="card" data-add-kind="${k}" style="text-align:start;padding:17px"><div style="font-size:25px">${i}</div><b style="display:block;margin-top:9px">${esc(n)}</b></button>`).join('')}</div></div>`;document.body.appendChild(m);m.querySelector('.close').onclick=()=>m.remove();m.addEventListener('click',e=>{if(e.target===m)m.remove()});m.querySelectorAll('[data-add-kind]').forEach(b=>b.onclick=()=>{const k=b.dataset.addKind;m.remove();if(k==='quick')quickAdd();else openEditor(null,k)})}
async function quickAdd(){const m=document.createElement('div');m.className='modal';m.innerHTML=`<div class="modal-card"><div class="modal-head"><h3>${esc(t().quickAdd)}</h3><button class="close">${I('close')}</button></div><p class="muted">${esc(t().paste)}</p><textarea class="textarea" id="quick-urls" style="min-height:170px" placeholder="https://play.google.com/store/apps/details?id=...\nhttps://example.com"></textarea><div class="form-actions"><button class="btn primary" id="extract-links">${I('search')} ${esc(t().extract)}</button><button class="btn" id="cancel-quick">${esc(t().cancel)}</button></div><div id="quick-results" style="margin-top:16px"></div></div>`;document.body.appendChild(m);m.querySelector('.close').onclick=()=>m.remove();m.querySelector('#cancel-quick').onclick=()=>m.remove();m.querySelector('#extract-links').onclick=async()=>{const urls=m.querySelector('#quick-urls').value.split(/\n+/).map(s=>s.trim()).filter(Boolean);if(!urls.length)return;const out=m.querySelector('#quick-results');out.innerHTML=`<div class="loading"><div class="spinner"></div></div>`;const rows=[];for(const url of urls.slice(0,20)){try{const r=await fetch('/api/extract',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({url})});const x=await r.json();rows.push({...x,sourceUrl:url,ok:r.ok})}catch(e){rows.push({sourceUrl:url,ok:false,error:t().errorGeneric})}}m._rows=rows;out.innerHTML=rows.map((r,i)=>`<div class="panel" style="margin-top:9px"><div style="display:flex;gap:11px;align-items:center"><div class="row-icon">${r.icon?`<img src="${esc(r.icon)}" alt="">`:r.ok?iconSvg(r.type):'⚠️'}</div><div style="flex:1"><b>${esc(r.title||r.sourceUrl)}</b><div class="subtle">${esc(r.platform||r.type||'')}</div></div><button class="btn mini" data-quick-edit="${i}">${esc(t().edit)}</button></div>${r.description?`<p class="muted" style="font-size:12px;margin:9px 0 0">${esc(r.description)}</p>`:''}</div>`).join('')+`<div class="form-actions"><button class="btn primary" id="save-quick">${esc(t().publishAll)}</button></div>`;out.querySelectorAll('[data-quick-edit]').forEach(b=>b.onclick=()=>{const r=rows[+b.dataset.quickEdit];m.remove();openEditor(null,r.type==='app'?r.type:'website',{prefill:r})});out.querySelector('#save-quick')?.addEventListener('click',async()=>{const okRows=rows.filter(x=>x.ok);for(const r of okRows){const draft=mapExtractedToForm(r);await saveRecord(draft,false)}m.remove();await loadAdmin();toast(t().saved,'ok')})};}
function mapExtractedToForm(r){const typ=r.type==='app'?'app':'website';return {type:typ,title:r.title||'',title_en:r.title||'',description:r.description||'',description_en:r.description||'',icon:r.icon||'',cover_image:r.coverImage||'',official_url:typ==='website'?r.finalUrl||r.sourceUrl:'',google_play_url:r.platform==='Google Play'?r.finalUrl||r.sourceUrl:'',app_store_url:r.platform==='App Store'?r.finalUrl||r.sourceUrl:'',developer:r.developer||'',platform:r.platform?[r.platform]:['Web'],published:false,featured:false,slug:slugify(r.title||'item')};}

function formField(label,name,value='',cls='',opts={}){return `<div class="field ${cls}"><label>${esc(label)}</label>${opts.select?`<select class="select" name="${esc(name)}">${opts.select.map(x=>`<option value="${esc(x[0])}" ${String(x[0])===String(value)?'selected':''}>${esc(x[1])}</option>`).join('')}</select>`:opts.textarea?`<textarea class="textarea" name="${esc(name)}" placeholder="">${esc(value)}</textarea>`:`<input class="input" name="${esc(name)}" value="${esc(value)}" ${opts.type?`type="${opts.type}"`:''}>`}</div>`}
function mediaField(label,name,url=''){return `<div class="field full"><label>${esc(label)}</label><div class="media-upload"><div class="upload-row"><input class="hidden" type="file" accept="image/png,image/jpeg,image/webp" data-file-input="${esc(name)}"><button type="button" class="btn mini" data-pick-file="${esc(name)}">${I('upload',15)} ${esc(t().upload)}</button>${url?`<img class="preview-img" data-preview="${esc(name)}" src="${esc(url)}" alt="">`:''}<button type="button" class="btn mini danger" data-clear-file="${esc(name)}">${esc(t().remove)}</button></div><input type="hidden" name="${esc(name)}" value="${esc(url||'')}"></div></div>`}
function openEditor(id,type,options={}){
  const rows=type==='prompt'?state.prompts:state.content;const item=id?rows.find(x=>x.id===id):null;const p=options.prefill||item||{};const cats=state.categories.filter(c=>type==='prompt'?true:true);
  const isPrompt=type==='prompt'; const title=p.title||'';
  const m=document.createElement('div');m.className='modal';m.innerHTML=`<div class="modal-card" style="max-width:980px"><div class="modal-head"><h3>${esc(id?t().edit:`${t().add} · ${typeLabel(type)}`)}</h3><button class="close">${I('close')}</button></div><form id="editor-form" class="admin-form"><div class="form-grid">${formField(t().name,'title',title)}${formField('Slug','slug',p.slug||slugify(title))}${formField(t().nameAr,'title_ar',p.title_ar||'')}${formField(t().nameEn,'title_en',p.title_en||title)}${formField(t().nameFr,'title_fr',p.title_fr||'')}${formField(t().shortDesc,'description',p.description||'', 'full',{textarea:true})}${formField(t().fullDesc,'full_description',p.full_description||'', 'full',{textarea:true})}${formField(t().category,'category_id',p.category_id||'', '',{select:[['','—'],...cats.map(c=>[c.id,`${c.icon||''} ${catName(c)}`])]})}${formField(t().tags,'tags',arr(p.tags).join(', '))}${!isPrompt?formField(t().features,'features',arr(p.features).join(', ')):''}${!isPrompt?formField(t().languages,'languages',arr(p.languages).join(', ')):''}${!isPrompt?formField(t().pricing,'pricing',p.pricing||'unknown','',{select:[['free',t().free],['freemium',t().freemium],['paid',t().paid],['unknown',t().unknown]]}):''}${!isPrompt?formField(t().platform,'platform',arr(p.platform).join(', ')):''}${!isPrompt?formField(t().developer,'developer',p.developer||''):''}${!isPrompt?formField(t().company,'company',p.company||''):''}${!isPrompt?formField(t().version,'version',p.version||''):''}${!isPrompt?formField('Last Updated','last_updated',p.last_updated||''):''}${isPrompt?formField(t().prompt,'prompt',p.prompt||'', 'full',{textarea:true}):''}${isPrompt?formField(t().aiTool,'ai_tool',p.ai_tool||''):''}${isPrompt?formField(t().language,'language',p.language||''):''}${isPrompt?formField(t().resultType,'resultType',p.result_type||''):''}${mediaField(isPrompt?t().icon:t().icon,'icon',p.icon||'')}${isPrompt?mediaField('Preview Image','preview_image',p.preview_image||''):mediaField(t().cover,'cover_image',p.cover_image||'')} ${!isPrompt?formField(t().official,'official_url',p.official_url||'', 'full'):''}${!isPrompt?formField(t().googlePlay,'google_play_url',p.google_play_url||''):''}${!isPrompt?formField(t().appStore,'app_store_url',p.app_store_url||''):''}${!isPrompt?formField(t().other,'other_official_url',p.other_official_url||''):''}${!isPrompt?formField(t().screens,'screenshots',arr(p.screenshots).join(', '),'full',{textarea:true}):''}<div class="field full"><div class="split"><label class="check-row"><input type="checkbox" name="featured" ${p.featured?'checked':''}> ${esc(t().featured)}</label><label class="check-row"><input type="checkbox" name="published" ${p.published?'checked':''}> ${esc(t().publishedStatus)}</label></div></div></div><div class="form-actions"><button class="btn" type="button" id="editor-draft">${esc(t().saveDraft)}</button><button class="btn" type="button" id="editor-preview">${I('eye',16)} ${esc(t().preview)}</button><button class="btn primary" type="button" id="editor-publish">${esc(t().publish)}</button>${id?`<button class="btn danger" type="button" id="editor-delete">${esc(t().delete)}</button>`:''}</div></form></div>`;document.body.appendChild(m);m.querySelector('.close').onclick=()=>m.remove();['icon',isPrompt?'preview_image':'cover_image'].forEach(n=>bindUpload(m,n));const submit=async(publishFlag)=>{const f=new FormData(m.querySelector('form'));const record=formToRecord(f,type,item);record.published=publishFlag;const saved=await saveRecord(record,!!id);if(saved){m.remove();await loadAdmin();toast(publishFlag?t().publishedToast:t().draftToast,'ok')}};m.querySelector('#editor-preview').onclick=()=>{const record=formToRecord(new FormData(m.querySelector('form')),type,item);openInlinePreview(record,type)};m.querySelector('#editor-draft').onclick=()=>submit(false);m.querySelector('#editor-publish').onclick=()=>submit(true);m.querySelector('#editor-delete')?.addEventListener('click',async()=>{if(confirm(t().deleteConfirm)){await deleteRecord(type,id);m.remove();await loadAdmin();toast(t().deleteDone,'ok')}})}
function bindUpload(m,name){const input=m.querySelector(`[data-file-input="${CSS.escape(name)}"]`),pick=m.querySelector(`[data-pick-file="${CSS.escape(name)}"]`),clear=m.querySelector(`[data-clear-file="${CSS.escape(name)}"]`);pick.onclick=()=>input.click();input.onchange=async()=>{const file=input.files?.[0];if(!file)return;try{const b=await optimizeImage(file);const url=await uploadFile(b,state.user.id);m.querySelector(`input[name="${CSS.escape(name)}"]`).value=url;let img=m.querySelector(`[data-preview="${CSS.escape(name)}"]`);if(!img){img=document.createElement('img');img.className='preview-img';m.querySelector('.upload-row').appendChild(img)}img.src=url}catch(e){toast(e.message||t().errorGeneric,'error')}};clear.onclick=()=>{m.querySelector(`input[name="${CSS.escape(name)}"]`).value='';m.querySelector(`[data-preview="${CSS.escape(name)}"]`)?.remove()}}
function openInlinePreview(item,type){const modal=document.createElement('div');modal.className='modal';const title=langTitle(item)||t().name,desc=langDesc(item)||'';if(type==='prompt'){modal.innerHTML=`<div class="modal-card"><div class="modal-head"><h3>${esc(t().preview)}</h3><button class="close">${I('close')}</button></div><section class="detail-hero" style="margin-top:14px"><div class="detail-icon">${item.icon?`<img src="${esc(item.icon)}" alt="">`:'🧠'}</div><div><span class="type-badge">${esc(t().prompts)}</span><h1>${esc(title)}</h1><p class="detail-sub">${esc(desc)}</p><div class="cta-row"><button class="btn primary" id="prev-copy">${I('copy')} ${esc(t().copy)}</button></div></div></section><div class="panel" style="margin-top:14px"><h2>${esc(t().prompt)}</h2><pre style="white-space:pre-wrap;word-break:break-word;line-height:1.8;font-family:ui-monospace,SFMono-Regular,Menlo,monospace;background:#090b0f;border:1px solid var(--line);padding:18px;border-radius:15px">${esc(item.prompt||'')}</pre></div></div>`;modal.querySelector('#prev-copy').onclick=()=>navigator.clipboard?.writeText(item.prompt||'').then(()=>toast(t().copied,'ok'))}else{modal.innerHTML=`<div class="modal-card"><div class="modal-head"><h3>${esc(t().preview)}</h3><button class="close">${I('close')}</button></div><section class="detail-hero" style="margin-top:14px"><div class="detail-icon">${item.icon?`<img src="${esc(item.icon)}" alt="">`:iconSvg(type)}</div><div><span class="type-badge">${esc(typeLabel(type))}</span><h1>${esc(title)}</h1><p class="detail-sub">${esc(desc)}</p><div class="meta-row"><span class="tag">${esc(pricingLabel(item.pricing))}</span>${item.category_id&&categoryMap().get(item.category_id)?`<span class="tag">${esc(catName(categoryMap().get(item.category_id)))}</span>`:''}</div></div></section><div class="panel" style="margin-top:14px"><h2>${esc(t().details)}</h2><div class="rich">${esc(item.full_description||desc)}</div></div>${item.cover_image?`<div class="panel" style="margin-top:14px"><img src="${esc(item.cover_image)}" alt="" style="width:100%;border-radius:15px"></div>`:''}</div>`}document.body.appendChild(modal);modal.querySelector('.close').onclick=()=>modal.remove();modal.addEventListener('click',e=>{if(e.target===modal)modal.remove()})}

async function optimizeImage(file){const max=1600;const bmp=await createImageBitmap(file);const scale=Math.min(1,max/Math.max(bmp.width,bmp.height));const c=document.createElement('canvas');c.width=Math.max(1,Math.round(bmp.width*scale));c.height=Math.max(1,Math.round(bmp.height*scale));c.getContext('2d').drawImage(bmp,0,0,c.width,c.height);const blob=await new Promise(r=>c.toBlob(r,'image/webp',.82));return new File([blob],`${slugify(file.name)}.webp`,{type:'image/webp'})}
async function uploadFile(file,userId){if(file.size>4_500_000)throw new Error('Image is still too large after optimization.');const path=`${userId}/${crypto.randomUUID()}.webp`;const {error}=await sb.storage.from('media').upload(path,file,{contentType:'image/webp',upsert:false,cacheControl:'31536000'});if(error)throw error;return sb.storage.from('media').getPublicUrl(path).data.publicUrl}
function formToRecord(f,type,item){const g=n=>String(f.get(n)||'').trim();const a=n=>arr(g(n));const base={id:item?.id,slug:slugify(g('slug')),title:g('title'),title_ar:g('title_ar'),title_en:g('title_en'),title_fr:g('title_fr'),description:g('description'),description_ar:g('description_ar'),description_en:g('description_en'),description_fr:g('description_fr'),category_id:g('category_id')||null,tags:a('tags'),icon:g('icon'),featured:f.get('featured')==='on',published:f.get('published')==='on'};if(type==='prompt')return {...base,prompt:g('prompt'),preview_image:g('preview_image'),ai_tool:g('ai_tool'),language:g('language'),result_type:g('resultType')};return {...base,type,full_description:g('full_description'),features:a('features'),languages:a('languages'),pricing:g('pricing')||'unknown',platform:a('platform'),developer:g('developer'),company:g('company'),version:g('version'),last_updated:g('last_updated'),cover_image:g('cover_image'),official_url:g('official_url'),google_play_url:g('google_play_url'),app_store_url:g('app_store_url'),other_official_url:g('other_official_url'),screenshots:a('screenshots')};}
async function saveRecord(record,isUpdate){const table=record.prompt!==undefined?'prompts':'content';const rowId=record.id;delete record.id;if(!isUpdate)record.created_by=state.user.id;try{let q;if(isUpdate){q=sb.from(table).update(record).eq('id',rowId)}else q=sb.from(table).insert(record);const {error}=await q;if(error)throw error;return true}catch(e){console.error(e);toast(e.message||t().errorGeneric,'error');return false}}
async function deleteRecord(type,id){const table=type==='prompt'?'prompts':'content';const {error}=await sb.from(table).update({deleted_at:new Date().toISOString(),published:false,featured:false}).eq('id',id);if(error)throw error}
async function loadAdmin(){const [{data:c,error:ce},{data:p,error:pe}]=await Promise.all([sb.from('content').select('*').is('deleted_at',null).order('updated_at',{ascending:false}).limit(500),sb.from('prompts').select('*').is('deleted_at',null).order('updated_at',{ascending:false}).limit(500)]);if(ce||pe)throw ce||pe;state.content=c||[];state.prompts=(p||[]).map(x=>({...x,type:'prompt'}));await router()}
function adminContent(){const rows=allAdminRows();shell(adminChrome('content',`<div class="admin-head"><div><h1>${esc(t().total)}</h1></div><button class="btn primary" id="open-add">${I('plus')} ${esc(t().add)}</button></div><div class="admin-toolbar"><input class="input" id="admin-filter" placeholder="${esc(t().search)}"><select class="select" id="admin-type"><option value="">${esc(t().all)}</option><option value="app">${esc(t().apps)}</option><option value="website">${esc(t().websites)}</option><option value="tool">${esc(t().tools)}</option><option value="ai_tool">${esc(t().ai)}</option><option value="prompt">${esc(t().prompts)}</option></select></div><div id="admin-table">${adminTable(rows)}</div>`));$('#open-add').onclick=()=>openAddChooser();const rer=()=>{const q=$('#admin-filter').value.toLowerCase();const typ=$('#admin-type').value;const filtered=rows.filter(x=>(!typ||x.type===typ)&&([langTitle(x),x.slug,...arr(x.tags)].join(' ').toLowerCase().includes(q)));$('#admin-table').innerHTML=adminTable(filtered)};$('#admin-filter').oninput=rer;$('#admin-type').onchange=rer;document.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>{const id=b.dataset.edit;const x=rows.find(v=>v.id===id);openEditor(id,x.type)});}
function categoriesPage(){shell(adminChrome('categories',`<div class="admin-head"><div><h1>${esc(t().categories)}</h1></div><button class="btn primary" id="add-cat">${I('plus')} ${esc(t().add)}</button></div><div class="table-wrap"><table class="table"><thead><tr><th>${esc(t().name)}</th><th>EN</th><th>FR</th><th></th></tr></thead><tbody>${state.categories.map(c=>`<tr><td>${esc(c.icon||'')} ${esc(c.name_ar)}</td><td>${esc(c.name_en)}</td><td>${esc(c.name_fr)}</td><td><button class="btn mini" data-cat-edit="${esc(c.id)}">${esc(t().edit)}</button></td></tr>`).join('')}</tbody></table></div>`));$('#add-cat').onclick=()=>categoryEditor(null);document.querySelectorAll('[data-cat-edit]').forEach(b=>b.onclick=()=>categoryEditor(state.categories.find(c=>c.id===b.dataset.catEdit)))}
function categoryEditor(c){const m=document.createElement('div');m.className='modal';m.innerHTML=`<div class="modal-card" style="max-width:620px"><div class="modal-head"><h3>${esc(t().category)}</h3><button class="close">${I('close')}</button></div><form class="form-grid" id="cat-form">${formField(t().nameAr,'name_ar',c?.name_ar||'')}${formField(t().nameEn,'name_en',c?.name_en||'')}${formField(t().nameFr,'name_fr',c?.name_fr||'')}${formField('Slug','slug',c?.slug||'')}${formField('Icon','icon',c?.icon||'')}${formField('Order','sort_order',c?.sort_order||0)}</form><div class="form-actions"><button class="btn primary" id="save-cat">${esc(t().save)}</button></div></div>`;document.body.appendChild(m);m.querySelector('.close').onclick=()=>m.remove();m.querySelector('#save-cat').onclick=async()=>{const f=new FormData(m.querySelector('form'));const rec={name_ar:f.get('name_ar'),name_en:f.get('name_en'),name_fr:f.get('name_fr'),slug:slugify(f.get('slug')),icon:f.get('icon'),sort_order:Number(f.get('sort_order')||0)};const {error}=c?await sb.from('categories').update(rec).eq('id',c.id):await sb.from('categories').insert(rec);if(error)return toast(error.message,'error');m.remove();await loadCategories();router();toast(t().saved,'ok')}}
function settingsPage(){
  const html = `<div class="admin-head"><div><h1>${esc(t().settings)}</h1></div></div>
    <div class="panel" style="max-width:760px"><h2>${esc(t().admin)}</h2><div class="facts">
      <div class="fact"><span>Email</span><b>${esc(state.user?.email||'—')}</b></div>
      <div class="fact"><span>Role</span><b>Admin</b></div>
    </div><div class="notice" style="margin-top:18px">Admin authorization is controlled server-side by <b>public.admin_allowlist</b> and PostgreSQL RLS. To add/remove an administrator, change that table in Supabase SQL Editor; no client-side permission flag is trusted.</div></div>
    <div class="panel" style="max-width:760px;margin-top:14px"><h2>Free-tier safety</h2><div class="rich">No paid API is required by the core site. The app does not contain code that enables billing or upgrades. Keep the Cloudflare and Supabase projects on their Free plans and monitor provider quotas manually.</div></div>`;
  shell(adminChrome('settings',html));
}
async function setupAdminBindings(){document.querySelectorAll('[data-admin-nav]').forEach(b=>b.onclick=()=>{const u=b.dataset.adminNav;if(u==='#')openAddChooser();else location.href=u});$('#admin-logout')?.addEventListener('click',async()=>{await sb.auth.signOut();location.href='/'});document.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>{const x=allAdminRows().find(v=>v.id===b.dataset.edit);if(x)openEditor(x.id,x.type)})}

async function ensureAdminData(){if(!state.isAdmin)return;const hasDrafts=state.content.some(x=>!x.published)||state.prompts.some(x=>!x.published);const needAdmin=location.pathname.startsWith('/admin');if(needAdmin&&!state._adminLoaded){await loadAdminData();state._adminLoaded=true}}
async function loadAdminData(){const [{data:c,error:ce},{data:p,error:pe}]=await Promise.all([sb.from('content').select('*').is('deleted_at',null).order('updated_at',{ascending:false}).limit(500),sb.from('prompts').select('*').is('deleted_at',null).order('updated_at',{ascending:false}).limit(500)]);if(ce||pe)throw ce||pe;state.content=c||[];state.prompts=(p||[]).map(x=>({...x,type:'prompt'}));}
async function router(){
  if(!state.booted)return; if(location.pathname==='/admin' || location.pathname.startsWith('/admin/')){if(!state.user){adminLogin();return}await refreshAdmin();if(!state.isAdmin){adminLogin();toast(t().notAdmin,'error');return}await loadAdminData();state._adminLoaded=true;if(location.pathname==='/admin')adminDashboard();else if(location.pathname==='/admin/content')adminContent();else if(location.pathname==='/admin/categories')categoriesPage();return}
  if(!localStorage.getItem('tk_welcomed') && location.pathname==='/'){welcome();return}
  if(location.pathname==='/')return home();if(location.pathname==='/search')return searchPage();if(location.pathname==='/favorites')return favoritesPage();
  const m=location.pathname.split('/').filter(Boolean);if(m.length===2)return detailPage(m[0],m[1]);return notFound();
}
window.addEventListener('popstate',router);document.addEventListener('click',e=>{const a=e.target.closest('a[href]');if(!a)return;const u=new URL(a.href);if(u.origin===location.origin&&!a.target){e.preventDefault();history.pushState({},'',u.pathname+u.search+u.hash);router()}});
init();
